{
  "tools": [
    {
      "name": "hammer_create_entity",
      "title": "Create Entity",
      "toolset": "hammer",
      "description": "Place an entity in the open map - a light, prop, spawn point, sound, anything hammer_entity_classes lists. Set any keyvalues in the same call. The user can undo this. Returns the new node.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "className": {
            "type": "string",
            "description": "The entity class, e.g. 'light_omni' or 'prop_static'. hammer_entity_classes lists them and documents their keyvalues."
          },
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'."
          },
          "angles": {
            "type": "string",
            "description": "Rotation as 'pitch,yaw,roll'."
          },
          "name": {
            "type": "string",
            "description": "The entity's name (targetname), for other entities to refer to it."
          },
          "keyValues": {
            "type": "object",
            "description": "Keyvalues as a json object, e.g. {\"model\": \"models/dev/box.vmdl\"} or {\"color\": \"255 200 150\"}. Strings are stored as given, numbers as written, booleans as 1/0 and arrays space separated - the way Hammer stores them."
          }
        },
        "required": [
          "className",
          "position"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "integer"
          },
          "Kind": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "ClassName": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Parent": {
            "type": "integer"
          },
          "GameObject": {
            "type": "string"
          },
          "Selected": {
            "type": "boolean"
          },
          "Visible": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_trace",
      "title": "Trace Ray",
      "toolset": "hammer",
      "description": "Trace a ray through the open map and report the first node it hits, where, and the surface normal - find the floor under a point, check what's in front of the camera, or probe where to place something. Traces Hammer's own geometry, so it works before the map is compiled.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "from": {
            "type": "string",
            "description": "Ray start as 'x,y,z'."
          },
          "to": {
            "type": "string",
            "description": "Ray end as 'x,y,z'."
          },
          "meshesOnly": {
            "type": "boolean",
            "description": "Only hit mesh geometry, ignoring entities and game objects.",
            "default": false
          },
          "skipToolsMaterials": {
            "type": "boolean",
            "description": "Don't hit tools materials like clip or trigger.",
            "default": false
          },
          "hitBackfaces": {
            "type": "boolean",
            "description": "Hit faces from behind too. A back face hit (the normal points along the ray) means the ray started inside something.",
            "default": false
          }
        },
        "required": [
          "from",
          "to"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Hit": {
            "type": "boolean"
          },
          "Position": {
            "type": "string"
          },
          "Normal": {
            "type": "string"
          },
          "Node": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "integer"
              },
              "Kind": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              },
              "ClassName": {
                "type": "string"
              },
              "Description": {
                "type": "string"
              },
              "Position": {
                "type": "string"
              },
              "Parent": {
                "type": "integer"
              },
              "GameObject": {
                "type": "string"
              },
              "Selected": {
                "type": "boolean"
              },
              "Visible": {
                "type": "boolean"
              }
            },
            "required": []
          }
        },
        "required": []
      }
    },
    {
      "name": "scene_trace",
      "title": "Scene Trace",
      "toolset": "scene",
      "description": "Trace a ray through the active scene's physics and report what it hits - find the floor, check line of sight, probe where something can be placed.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "from": {
            "type": "string",
            "description": "Ray start as 'x,y,z'."
          },
          "to": {
            "type": "string",
            "description": "Ray end as 'x,y,z'."
          }
        },
        "required": [
          "from",
          "to"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Hit": {
            "type": "boolean",
            "description": "Whether the trace hit anything."
          },
          "StartedSolid": {
            "type": "boolean",
            "description": "Whether the trace started inside something solid."
          },
          "EndPosition": {
            "type": "string",
            "description": "Where the trace ended - the hit point, or the requested end on a miss."
          },
          "Normal": {
            "type": "string",
            "description": "The hit surface normal."
          },
          "Fraction": {
            "type": "number",
            "description": "How far along the ray the hit was, 0 to 1."
          },
          "Distance": {
            "type": "number",
            "description": "How far the trace travelled, in units."
          },
          "GameObject": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              }
            },
            "required": [],
            "description": "The game object hit. Null on a miss."
          },
          "Component": {
            "type": "string",
            "description": "The component type hit. Null on a miss."
          }
        },
        "required": []
      }
    }
  ],
  "total": 128
}
